package main

import (
	"context"
	"database/sql"
	"fmt"
	"log"
	"net/http"

	"github.com/gin-gonic/gin"
	_ "github.com/lib/pq"
	"google.golang.org/grpc"
	"google.golang.org/grpc/metadata"
)

var db *sql.DB
var grpcConn *grpc.ClientConn

func init() {
	var err error
	db, err = sql.Open("postgres", "host=localhost dbname=app sslmode=disable")
	if err != nil {
		log.Fatal(err)
	}
	grpcConn, err = grpc.Dial("backend-service:9090", grpc.WithInsecure())
	if err != nil {
		log.Fatal(err)
	}
}

// extractTenantFromJWT parses the JWT and returns tenant_id claim
func extractTenantFromJWT(c *gin.Context) string {
	// In production this validates signature - simplified for brevity
	return c.GetHeader("X-Tenant-ID")
}

// setRLSContext sets the PostgreSQL session variable for RLS
func setRLSContext(ctx context.Context, tenantID string) (*sql.Conn, error) {
	conn, err := db.Conn(ctx)
	if err != nil {
		return nil, err
	}
	// Set the session-level variable that RLS policies reference
	_, err = conn.ExecContext(ctx, fmt.Sprintf("SET app.current_tenant = '%s'", tenantID))
	if err != nil {
		conn.Close()
		return nil, err
	}
	return conn, nil
}

// forwardToGRPC forwards the request to the backend gRPC service
func forwardToGRPC(ctx context.Context, tenantID string, resourceID string) (string, error) {
	// Attach tenant context as gRPC metadata for downstream services
	md := metadata.Pairs(
		"x-tenant-id", tenantID,
		"x-request-source", "gin-gateway",
	)
	outCtx := metadata.NewOutgoingContext(ctx, md)

	// Simulated unary call - in real code this calls a generated client stub
	var header metadata.MD
	err := grpcConn.Invoke(outCtx, "/api.ResourceService/GetResource",
		&struct{ ID string }{ID: resourceID}, &struct{}{}, grpc.Header(&header))
	if err != nil {
		return "", err
	}
	return "ok", nil
}

func getResource(c *gin.Context) {
	tenantID := extractTenantFromJWT(c)
	if tenantID == "" {
		c.JSON(http.StatusUnauthorized, gin.H{"error": "missing tenant"})
		return
	}

	resourceID := c.Param("id")

	// Query with RLS - the policy should enforce tenant isolation
	conn, err := setRLSContext(c.Request.Context(), tenantID)
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "db error"})
		return
	}
	defer conn.Close()

	var name string
	err = conn.QueryRowContext(c.Request.Context(),
		"SELECT name FROM resources WHERE id = $1", resourceID).Scan(&name)
	if err != nil {
		c.JSON(http.StatusNotFound, gin.H{"error": "not found"})
		return
	}

	// Also fetch from gRPC backend for enrichment
	_, err = forwardToGRPC(c.Request.Context(), tenantID, resourceID)
	if err != nil {
		log.Printf("grpc enrichment failed: %v", err)
	}

	c.JSON(http.StatusOK, gin.H{"name": name, "tenant": tenantID})
}

func listResources(c *gin.Context) {
	tenantID := extractTenantFromJWT(c)
	if tenantID == "" {
		c.JSON(http.StatusUnauthorized, gin.H{"error": "missing tenant"})
		return
	}

	conn, err := setRLSContext(c.Request.Context(), tenantID)
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "db error"})
		return
	}
	defer conn.Close()

	rows, err := conn.QueryContext(c.Request.Context(),
		"SELECT id, name FROM resources")
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "query error"})
		return
	}
	defer rows.Close()

	var results []map[string]string
	for rows.Next() {
		var id, name string
		rows.Scan(&id, &name)
		results = append(results, map[string]string{"id": id, "name": name})
	}
	c.JSON(http.StatusOK, results)
}

func main() {
	r := gin.Default()
	r.GET("/resources/:id", getResource)
	r.GET("/resources", listResources)
	r.Run(":8080")
}
